public class InstallIdentityProbe48 implements InstallHandler {
 private static Map<String,Object> observed;
 public void onInstall(InstallContext context) {
  Id organization=context.organizationId();
  Version previous=context.previousVersion();
  observed=new Map<String,Object>{'organizationPresent'=>organization!=null,'organizationMatches'=>organization==UserInfo.getOrganizationId(),'organizationCaseMatches'=>organization==context.OrganizationId(),'previousVersion'=>previous==null?null:previous.toString(),'upgrade'=>context.isUpgrade(),'push'=>context.isPush(),'installerMatches'=>context.installerId()==UserInfo.getUserId()};
 }
 public static List<Object> run() {
  List<Object> rows=new List<Object>();
  Test.testInstall(new InstallIdentityProbe48(),null);
  rows.add(observed);
  Test.testInstall(new InstallIdentityProbe48(),new Version(1,2,3),true);
  rows.add(observed);
  return rows;
 }
}

